class Solution:
    def maxScore(self, n: int, edges: List[List[int]]) -> int:
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b); adj[b].append(a)
        seen = [False] * n
        comps = []
        for i in range(n):
            if seen[i]:
                continue
            st = [i]; seen[i] = True; sz = 0; m = 0
            while st:
                u = st.pop(); sz += 1; m += len(adj[u])
                for v in adj[u]:
                    if not seen[v]:
                        seen[v] = True; st.append(v)
            comps.append((sz, m // 2 == sz))
        comps.sort(key=lambda x: (-x[0], -x[1]))
        pos = 0; ans = 0
        for sz, cyc in comps:
            block = list(range(n - pos, n - pos - sz, -1))
            pos += sz
            block.sort()
            if cyc:
                order = [0] + list(range(1, sz, 2)) + list(range(sz - 2 if sz % 2 == 0 else sz - 1, 0, -2))
            else:
                order = list(range(0, sz, 2)) + list(range(sz - 1 if sz % 2 == 0 else sz - 2, 0, -2))
            arr = [block[i] for i in order]
            for i in range(sz):
                if cyc:
                    ans += arr[i] * arr[(i + 1) % sz]
                elif i < sz - 1:
                    ans += arr[i] * arr[i + 1]
        return ans

