class Solution {
public:
    long long maxScore(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<char> seen(n, 0);
        vector<pair<int,int>> comps;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            vector<int> st = {i}; seen[i] = 1;
            int sz = 0, m = 0;
            while (!st.empty()) {
                int u = st.back(); st.pop_back();
                sz++; m += adj[u].size();
                for (int v : adj[u]) if (!seen[v]) { seen[v] = 1; st.push_back(v); }
            }
            comps.push_back({sz, m / 2 == sz});
        }
        sort(comps.begin(), comps.end(), [](auto& a, auto& b) {
            return a.first != b.first ? a.first > b.first : a.second > b.second;
        });
        long long ans = 0; int pos = 0;
        for (auto& [sz, cyc] : comps) {
            vector<long long> block(sz);
            for (int i = 0; i < sz; i++) block[i] = n - pos - i;
            pos += sz;
            sort(block.begin(), block.end());
            vector<int> order;
            if (cyc) {
                order.push_back(0);
                for (int i = 1; i < sz; i += 2) order.push_back(i);
                for (int i = (sz % 2 == 0 ? sz - 2 : sz - 1); i > 0; i -= 2) order.push_back(i);
            } else {
                for (int i = 0; i < sz; i += 2) order.push_back(i);
                for (int i = (sz % 2 == 0 ? sz - 1 : sz - 2); i > 0; i -= 2) order.push_back(i);
            }
            vector<long long> arr(sz);
            for (int i = 0; i < sz; i++) arr[i] = block[order[i]];
            for (int i = 0; i < sz; i++)
                if (cyc) ans += arr[i] * arr[(i + 1) % sz];
                else if (i + 1 < sz) ans += arr[i] * arr[i + 1];
        }
        return ans;
    }
};

