class Solution {
    public long maxScore(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        boolean[] seen = new boolean[n];
        List<int[]> comps = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            Deque<Integer> st = new ArrayDeque<>(); st.push(i); seen[i] = true;
            int sz = 0, m = 0;
            while (!st.isEmpty()) {
                int u = st.pop(); sz++; m += adj.get(u).size();
                for (int v : adj.get(u)) if (!seen[v]) { seen[v] = true; st.push(v); }
            }
            comps.add(new int[]{sz, m / 2 == sz ? 1 : 0});
        }
        comps.sort((a, b) -> a[0] != b[0] ? b[0] - a[0] : b[1] - a[1]);
        long ans = 0; int pos = 0;
        for (int[] cp : comps) {
            int sz = cp[0]; boolean cyc = cp[1] == 1;
            long[] block = new long[sz];
            for (int i = 0; i < sz; i++) block[i] = n - pos - i;
            pos += sz;
            Arrays.sort(block);
            List<Integer> order = new ArrayList<>();
            if (cyc) {
                order.add(0);
                for (int i = 1; i < sz; i += 2) order.add(i);
                for (int i = (sz % 2 == 0 ? sz - 2 : sz - 1); i > 0; i -= 2) order.add(i);
            } else {
                for (int i = 0; i < sz; i += 2) order.add(i);
                for (int i = (sz % 2 == 0 ? sz - 1 : sz - 2); i > 0; i -= 2) order.add(i);
            }
            long[] arr = new long[sz];
            for (int i = 0; i < sz; i++) arr[i] = block[order.get(i)];
            for (int i = 0; i < sz; i++)
                if (cyc) ans += arr[i] * arr[(i + 1) % sz];
                else if (i + 1 < sz) ans += arr[i] * arr[i + 1];
        }
        return ans;
    }
}

