var maxScore = function(n, edges) {
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
    const seen = new Array(n).fill(false);
    const comps = [];
    for (let i = 0; i < n; i++) {
        if (seen[i]) continue;
        const st = [i]; seen[i] = true;
        let sz = 0, m = 0;
        while (st.length) {
            const u = st.pop(); sz++; m += adj[u].length;
            for (const v of adj[u]) if (!seen[v]) { seen[v] = true; st.push(v); }
        }
        comps.push([sz, m / 2 === sz ? 1 : 0]);
    }
    comps.sort((a, b) => b[0] - a[0] || b[1] - a[1]);
    let pos = 0, ans = 0;
    for (const [sz, cyc] of comps) {
        const block = [];
        for (let i = 0; i < sz; i++) block.push(n - pos - i);
        pos += sz;
        block.sort((a, b) => a - b);
        const order = [];
        if (cyc) {
            order.push(0);
            for (let i = 1; i < sz; i += 2) order.push(i);
            for (let i = (sz % 2 === 0 ? sz - 2 : sz - 1); i > 0; i -= 2) order.push(i);
        } else {
            for (let i = 0; i < sz; i += 2) order.push(i);
            for (let i = (sz % 2 === 0 ? sz - 1 : sz - 2); i > 0; i -= 2) order.push(i);
        }
        const arr = order.map(i => block[i]);
        for (let i = 0; i < sz; i++)
            if (cyc) ans += arr[i] * arr[(i + 1) % sz];
            else if (i + 1 < sz) ans += arr[i] * arr[i + 1];
    }
    return ans;
};
